                if (jproperty.Value.ToString().IndexOf("[") >= 0 || jproperty.Value.ToString().IndexOf("{") >= 0)
                {
                    resultObj.values[jproperty.Name] = ParseObjectAlternativeObjectValue(jproperty.Value);
